#include <iostream>
#include <iomanip>

int main() {
    // 1. Case-sensitive and proper initialization
    double interestRate{0.05};
    double principal{1000.0};
    double interest = interestRate * principal;
    std::cout << "Interest: " << interest << "\n";

    // 2. Floating-point precision and truncation issue
    double amount{10.03};
    double scaledAmount = amount * 100.0;
    int truncatedCents = static_cast<int>(scaledAmount);

    std::cout << std::fixed << std::setprecision(14);
    std::cout << "Scaled raw: " << scaledAmount << "\n";
    std::cout << "Truncated cents: " << truncatedCents << "\n";

    // 3. Round-off demonstration
    float a{1000.43f};
    float b{1000.0f};
    std::cout << std::setprecision(6);
    std::cout << "float subtraction: " << (a - b) << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int celsiusInput = 25;

    // Incorrect: integer division 9 / 5 truncates to 1
    double wrongFahrenheit = (9 / 5) * celsiusInput + 32;

    // Correct: floating-point literal forces floating-point division
    double correctFahrenheit = (9.0 / 5.0) * celsiusInput + 32.0;

    // Correct using static_cast for integer variables
    int num1 = 9;
    int num2 = 5;
    double castedFahrenheit = (static_cast<double>(num1) / num2) * celsiusInput + 32.0;

    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Incorrect result: " << wrongFahrenheit << "\n";
    std::cout << "Correct literal:  " << correctFahrenheit << "\n";
    std::cout << "Correct cast:     " << castedFahrenheit << "\n";

    return 0;
}
